import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";import"./chunks/assets.JoaDwx61.js";var i=JSON.parse(`{"title":"Installing Business Central On-Premises Using Docker Desktop","description":"","frontmatter":{},"headers":[],"relativePath":"installation-and-setup/installing-business-central-on-premises-on-docker-desktop.md","filePath":"installation-and-setup/installing-business-central-on-premises-on-docker-desktop.md"}`),a={name:`installation-and-setup/installing-business-central-on-premises-on-docker-desktop.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="installing-business-central-on-premises-using-docker-desktop" tabindex="-1">Installing Business Central On-Premises Using Docker Desktop <a class="header-anchor" href="#installing-business-central-on-premises-using-docker-desktop" aria-label="Permalink to “Installing Business Central On-Premises Using Docker Desktop”">​</a></h1><p>We can run Microsoft Dynamics 365 Business Central on-premises inside a Docker container. This allows us to practice AL development without setting up the entire environment manually on Windows.</p><p><strong>Limitation:</strong> Unlike Business Central online, a local on-premises installation does not provide the online Business Central admin center. However, it supports much of the development functionality needed to learn AL.</p><h2 id="step-1-install-docker-desktop" tabindex="-1">Step 1: Install Docker Desktop <a class="header-anchor" href="#step-1-install-docker-desktop" aria-label="Permalink to “Step 1: Install Docker Desktop”">​</a></h2><p>Install Docker Desktop using the appropriate Windows installation tutorial.</p><h3 id="enable-windows-containers" tabindex="-1">Enable Windows Containers <a class="header-anchor" href="#enable-windows-containers" aria-label="Permalink to “Enable Windows Containers”">​</a></h3><p>Business Central on-premises containers use <strong>Windows containers</strong>, which run Windows-based applications in isolated environments. Docker must therefore be configured to support Windows containers rather than Linux containers.</p><p>Once Docker Desktop is installed:</p><ol><li>Run Docker Desktop as an administrator.</li><li>Wait for the Docker engine to start.</li><li>Find the Docker icon in the Windows system tray.</li><li>Right-click the icon and select <strong>Switch to Windows containers</strong>.</li></ol><blockquote><p><strong>Note:</strong> Windows containers require compatible Windows features and system configuration. If Docker reports that Windows container support is unavailable, run the commands in the &quot;Enabling Windows Features&quot; section below.</p></blockquote><h2 id="step-2-install-bccontainerhelper" tabindex="-1">Step 2: Install BCContainerHelper <a class="header-anchor" href="#step-2-install-bccontainerhelper" aria-label="Permalink to “Step 2: Install BCContainerHelper”">​</a></h2><p><strong>BCContainerHelper</strong> is a PowerShell module that simplifies creating and managing Business Central Docker containers. It provides commands for downloading Business Central artifacts, creating containers, and performing common development and administration tasks.</p><p>Open PowerShell ISE as an administrator and run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Install-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BCContainerHelper </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span></code></pre></div><p>This installs the module. The <code>-Force</code> parameter allows the installation to proceed without some interactive prompts.</p><p>To display an introduction to the module and its available functions, run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Write-BCContainerHelperWelcomeText</span></span></code></pre></div><p>See <a href="/installation-and-setup/troubleshooting-powershell-errors.html">troubleshooting powershell errors</a> section if this doesn&#39;t work.</p><h2 id="step-3-list-and-retrieve-business-central-artifacts" tabindex="-1">Step 3: List and Retrieve Business Central Artifacts <a class="header-anchor" href="#step-3-list-and-retrieve-business-central-artifacts" aria-label="Permalink to “Step 3: List and Retrieve Business Central Artifacts”">​</a></h2><h3 id="what-are-artifacts" tabindex="-1">What are artifacts? <a class="header-anchor" href="#what-are-artifacts" aria-label="Permalink to “What are artifacts?”">​</a></h3><p><strong>Business Central artifacts</strong> are the installation files and related resources for a particular Business Central version, including the files needed to create a container.</p><p>BCContainerHelper uses artifact URLs to identify which version and localization of Business Central to install.</p><p>For example, <code>w1</code> represents the worldwide localization.</p><h3 id="list-available-artifacts" tabindex="-1">List available artifacts <a class="header-anchor" href="#list-available-artifacts" aria-label="Permalink to “List available artifacts”">​</a></h3><p>Run the following command to list all available on-premises artifacts for the worldwide localization:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-BcArtifactUrl</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type OnPrem </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">country w1 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">select All</span></span></code></pre></div><h3 id="retrieve-the-latest-artifact-url" tabindex="-1">Retrieve the latest artifact URL <a class="header-anchor" href="#retrieve-the-latest-artifact-url" aria-label="Permalink to “Retrieve the latest artifact URL”">​</a></h3><p>To retrieve the URL for the latest available on-premises artifact for the worldwide localization, run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-BcArtifactUrl</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type OnPrem </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">country w1 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">select Latest</span></span></code></pre></div><p>The returned URL identifies the artifact that will be used when creating the container.</p><p><strong>Important:</strong> The latest artifact changes as Microsoft releases new versions. You can use a specific artifact URL when you need to work with a particular version.</p><h2 id="step-4-create-the-business-central-docker-container" tabindex="-1">Step 4: Create the Business Central Docker Container <a class="header-anchor" href="#step-4-create-the-business-central-docker-container" aria-label="Permalink to “Step 4: Create the Business Central Docker Container”">​</a></h2><p>Open a new PowerShell script (<code>.ps1</code>) in PowerShell ISE and enter the following code:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$password </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1234&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$securePassword </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ConvertTo-SecureString</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String $password </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AsPlainText </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$artifactUrl </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://bcartifacts-exdbf9fwegejdqak.b02.azurefd.net/onprem/29.0.54011.55407/w1&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$containerName </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bcserv&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$credential </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> New-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pscredential </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;admin&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $securePassword</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-BcContainer</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">accept_eula </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">accept_outdated </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">updateHosts </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">artifactUrl $artifactUrl </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">containerName $containerName </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">credential $credential </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth UserPassword </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shortcuts StartMenu </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memoryLimit 8G </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">alwaysPull</span></span></code></pre></div><p>Run the script and allow the process to complete. Creating a container may take considerable time because the required images and artifacts must be downloaded and configured.</p><h3 id="understanding-the-script" tabindex="-1">Understanding the script <a class="header-anchor" href="#understanding-the-script" aria-label="Permalink to “Understanding the script”">​</a></h3><p><strong>1. Define the password and credentials</strong></p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$password </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1234&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$securePassword </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ConvertTo-SecureString</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String $password </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AsPlainText </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$credential </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> New-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pscredential </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;admin&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $securePassword</span></span></code></pre></div><p>These commands define the password and create credentials for the Business Central user.</p><p><code>ConvertTo-SecureString</code> converts the plain-text password into a PowerShell secure string, which is then used to construct the credentials.</p><p><em>Security note:</em> The password above is for demonstration only. Use a stronger password for your own environment, and avoid hardcoding real credentials in scripts.</p><p><strong>2. Specify the artifact URL</strong></p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$artifactUrl </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://bcartifacts-exdbf9fwegejdqak.b02.azurefd.net/onprem/29.0.54011.55407/w1&quot;</span></span></code></pre></div><p>This identifies the Business Central version and localization to install. Here, the URL points to version <code>29.0.54011.55407</code>, worldwide localization.</p><p><strong>3. Specify the container name</strong></p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$containerName </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bcserv&quot;</span></span></code></pre></div><p>This assigns the name <code>bcserv</code> to the container, making it easier to identify and manage in Docker Desktop.</p><p><strong>4. Create the container</strong></p><p>The <code>New-BcContainer</code> command creates and configures the Business Central environment.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Purpose</th></tr></thead><tbody><tr><td><code>-accept_eula</code></td><td>Accepts the applicable license terms.</td></tr><tr><td><code>-accept_outdated</code></td><td>Allows the use of artifacts that BCContainerHelper considers outdated.</td></tr><tr><td><code>-updateHosts</code></td><td>Updates the Windows hosts file to support resolving the container&#39;s hostname.</td></tr><tr><td><code>-artifactUrl</code></td><td>Specifies the Business Central artifact to install.</td></tr><tr><td><code>-containerName</code></td><td>Sets the container&#39;s name.</td></tr><tr><td><code>-credential</code></td><td>Supplies the credentials used to configure the environment.</td></tr><tr><td><code>-auth UserPassword</code></td><td>Configures username-and-password authentication.</td></tr><tr><td><code>-shortcuts StartMenu</code></td><td>Creates Start Menu shortcuts for convenient access.</td></tr><tr><td><code>-memoryLimit 8G</code></td><td>Sets the container&#39;s memory limit to 8 GB.</td></tr><tr><td><code>-alwaysPull</code></td><td>Instructs the helper to pull the required image rather than relying solely on a locally available copy.</td></tr></tbody></table><p>The backtick (<code>\`</code>) at the end of each line continues the PowerShell command onto the next line.</p><p><strong>Troubleshooting tip:</strong> Downloading artifacts and creating the container can take time and consume significant bandwidth. If the operation times out, investigate the error and network connection before assuming that the computer lacks sufficient resources.</p><h2 id="step-5-open-business-central" tabindex="-1">Step 5: Open Business Central <a class="header-anchor" href="#step-5-open-business-central" aria-label="Permalink to “Step 5: Open Business Central”">​</a></h2><p>Once the container has been created successfully:</p><ol><li>Open Docker Desktop.</li><li>Locate the container named <code>bcserv</code>.</li><li>Confirm that the container is running.</li><li>Open the container&#39;s details and locate the Business Central web client URL.</li></ol><p><img src="/running-bc-container.png" alt="Running BC Container" width="855" height="465"></p><ol start="5"><li>Open the URL in your browser.</li><li>Sign in using the username and password configured in Step 4.</li></ol><p>If the web client loads and you can sign in, your local Business Central environment is ready to use.</p><h2 id="enabling-windows-features" tabindex="-1">Enabling Windows Features <a class="header-anchor" href="#enabling-windows-features" aria-label="Permalink to “Enabling Windows Features”">​</a></h2><p>During troubleshooting, the following PowerShell command was used:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Enable-WindowsOptionalFeature</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Online </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FeatureName </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Microsoft-Hyper-V&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Containers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">All</span></span></code></pre></div><p>This command enables two Windows optional features:</p><ul><li><strong>Microsoft-Hyper-V:</strong> Provides Microsoft&#39;s virtualization technology, which can support the virtualized infrastructure required by some container configurations.</li><li><strong>Containers:</strong> Enables Windows container functionality.</li></ul><p>The parameters mean:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Purpose</th></tr></thead><tbody><tr><td><code>-Online</code></td><td>Applies the change to the currently running Windows installation.</td></tr><tr><td><code>-FeatureName</code></td><td>Specifies the Windows features to enable.</td></tr><tr><td><code>-All</code></td><td>Also enables any required parent features.</td></tr></tbody></table><p><strong>Important:</strong> Run this command in an elevated PowerShell session. Enabling these features may require a Windows restart. Hyper-V also has hardware and Windows edition requirements.</p><p>This command is a troubleshooting measure, not a command that must be run on every machine. Verify which feature is missing before changing your Windows configuration.</p>`,67)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};